    "description": "Assistant attempted to update flight reservation EUJUY6 by changing return flight dates from May 16 to May 18, using credit_card_7872117 for fare differences, while keeping cabin class as basic_economy."
  },
  "applicable_norms": [
    {
      "policy_source_id": "q7",
      "interpretation": "Before updating flight reservations, the assistant must list the action details and obtain explicit user confirmation (yes) to proceed.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q7",
      "interpretation": "The assistant must not make tool calls simultaneously with sending messages to the user.",
      "modality": "FORBID"
    },
    {
      "policy_source_id": "q10",
      "interpretation": "Basic economy flights cannot be modified (only other reservations can be modified without changing origin, destination, and trip type).",
      "modality": "FORBID"
    },
    {
      "policy_source_id": "q10",
      "interpretation": "The assistant must ensure that all flights in the reservation are included in the update, even if unchanged.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q10",
      "interpretation": "If the price after modification is higher, the user must pay the difference using a valid payment method (credit card or gift card).",
